const dictionaries: Record<ResolvedLocale, Dictionary> = { "zh-TW": zhTW, en, ja, th, ko };

function systemLocaleRaw() {
  try { return Intl.DateTimeFormat().resolvedOptions().locale || "en"; } catch { return "en"; }
}

export function normalizeLocale(locale: string | null | undefined): ResolvedLocale {
  const value = (locale ?? "").toLowerCase();
  if (value.startsWith("zh")) return "zh-TW";
  if (value.startsWith("ja")) return "ja";
  if (value.startsWith("th")) return "th";
  if (value.startsWith("ko")) return "ko";
  return "en";
}

export function resolveLanguage(language: AppLanguage): ResolvedLocale {
  return language === "system" ? normalizeLocale(systemLocaleRaw()) : language;
}

let currentLocale: ResolvedLocale = normalizeLocale(systemLocaleRaw());

export function setCurrentLocale(locale: ResolvedLocale) { currentLocale = locale; }
export function getCurrentLocale() { return currentLocale; }

export function translate(key: string, vars: Vars = {}, locale: ResolvedLocale = currentLocale): string {
  const template = dictionaries[locale][key] ?? zhTW[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(vars[name] ?? `{${name}}`));
}

export function numberLocale(locale: ResolvedLocale) {
  return locale === "zh-TW" ? "zh-TW" : locale === "en" ? "en-US" : locale === "ja" ? "ja-JP" : locale === "th" ? "th-TH" : "ko-KR";
}

export function formatNumber(value: number, locale: ResolvedLocale = currentLocale) {
  return new Intl.NumberFormat(numberLocale(locale)).format(value);
}

export function formatDate(timestamp: number | Date, options: Intl.DateTimeFormatOptions, locale: ResolvedLocale = currentLocale) {
  return new Intl.DateTimeFormat(numberLocale(locale), options).format(timestamp);
}

export async function readLanguageSetting(): Promise<AppLanguage> {
  try {
    const raw = await AsyncStorage.getItem(LANGUAGE_STORAGE_KEY);
    if (raw === "system" || raw === "zh-TW" || raw === "en" || raw === "ja" || raw === "th" || raw === "ko") return raw;
  } catch {}
  return "system";
}

export async function writeLanguageSetting(language: AppLanguage) {
  await AsyncStorage.setItem(LANGUAGE_STORAGE_KEY, language);
}
